                    moves.append(((i, j), (i, j+1)))
            elif board[i][j] == 'U':
                if i > 0 and board[i-1][j] != 'D':
                    moves.append(((i, j), (i-1, j)))
            elif board[i][j] == 'D':
                if i < n - 1 and board[i+1][j] != 'U':
                    moves.append(((i, j), (i+1, j)))
    return moves

def count_distinct_photos(n, m, board):
    free_cells = get_free_cells(board, n, m)
    moves = get_moves(board, n, m)

    distinct_photos = set()
    for i in range(len(free_cells)):
        for j in range(i + 1, len(free_cells)):
            for move in moves:
